const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define locations
  const airport = ee.Geometry.Point([85.8178, 20.2543]); // Biju Patnaik Airport
  const saheed = ee.Geometry.Point([85.848691, 20.290813]); // Saheed Nagar

  // Define date range
  const startDate = '2019-04-30';
  const endDate = '2019-05-05';

  // Get VIIRS nighttime lights data
  const viirs = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG')
    .filterDate(startDate, endDate);

  // Check collection size
  const count = viirs.size().getInfo();
  if (count === 0) {
    print("No VIIRS images found in date range");
    print("<answer>C1</answer>");
    return;
  }

  print(`VIIRS Images: ${count}`);

  // Function to get brightness for a location
  function getBrightness(location, name) {
    const first = viirs.filterDate('2019-04-30', '2019-05-01').first();
    const last = viirs.filterDate('2019-05-04', '2019-05-06').first();

    if (!first || !last) {
      print(`${name}: Missing start or end image`);
      return null;
    }

    const firstVal = first.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: location,
      scale: 1000,
      maxPixels: 1e9
    }).get('avg_rad').getInfo();

    const lastVal = last.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: location,
      scale: 1000,
      maxPixels: 1e9
    }).get('avg_rad').getInfo();

    // Check for valid pixels
    if (firstVal === null || lastVal === null) {
      print(`${name}: No valid pixels`);
      return null;
    }

    const change = lastVal - firstVal;
    print(`${name}: ${firstVal.toFixed(2)} -> ${lastVal.toFixed(2)} (Δ: ${change.toFixed(2)})`);
    return change;
  }

  // Get brightness changes
  const airportChange = getBrightness(airport, "Airport");
  const saheedChange = getBrightness(saheed, "Saheed");

  // Validate results
  if (airportChange === null || saheedChange === null) {
    print("Missing data for one or both locations");
    print("<answer>C2</answer>");
    return;
  }

  if (!isFinite(airportChange) || !isFinite(saheedChange)) {
    print("Invalid calculation result");
    print("<answer>C3</answer>");
    return;
  }

  // Compare changes - looking for greater decrease (more negative)
  const airportDecreasedMore = airportChange < saheedChange;

  print(`Airport Δ: ${airportChange.toFixed(2)}`);
  print(`Saheed Δ: ${saheedChange.toFixed(2)}`);

  if (airportDecreasedMore) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
